paragraph.math:
$$\begin{array}{l}
  {\frac{\sqrt{1 + h} - 1}{h} = \frac{({\sqrt{1 + h} - 1})({\sqrt{1 + h} + 1})}{h{({\sqrt{1 + h} + 1})}}\qquad{({\sqrt{a} - \sqrt{b}})({\sqrt{a} + \sqrt{b}}) = a - b}} \\
  {\phantom{\frac{\sqrt{1 + h} - 1}{h}} = \frac{1 + h - 1}{h{({\sqrt{1 + h} + 1})}}} \\
  {\phantom{\frac{\sqrt{1 + h} - 1}{h}} = \frac{h}{h{({\sqrt{1 + h} + 1})}}} \\
  {\phantom{\frac{\sqrt{1 + h} - 1}{h}} = \frac{1}{\sqrt{1 + h} + 1}}
  \end{array}$$

$$\begin{array}{l}
  {\lim\limits_{x\rightarrow - 1}\frac{x^{2} - x - 2}{2x^{2} - x - 3} = \lim\limits_{x\rightarrow - 1}\frac{\left( {x + 1} \right)\left( {x - 2} \right)}{\left( {x + 1} \right)\left( {2x - 3} \right)}} \\
  {\phantom{\lim\limits_{x\rightarrow - 1}\frac{x^{2} - x - 2}{2x^{2} - x - 3}} = \lim\limits_{x\rightarrow - 1}\frac{x - 2}{2x - 3}\qquad{\text{Cancel the common factors}.}} \\
  {\phantom{\lim\limits_{x\rightarrow - 1}\frac{x^{2} - x - 2}{2x^{2} - x - 3}} = \frac{- 1 - 2}{2\left( {- 1} \right) - 3}} \\
  {\phantom{\lim\limits_{x\rightarrow - 1}\frac{x^{2} - x - 2}{2x^{2} - x - 3}} = \frac{3}{5}}
  \end{array}$$
